@Component("account-handler")
@ProcessingGroup("account-processing-group")
public class AccountEventHandler {
	
	// core constructor
	AccountEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAccountEvent
     */
    @EventHandler
    public void handle( CreateAccountEvent event) {
        entityManager.persist(new Account(event.getAccountId(), event.getAccountNumber(), event.getIban(), event.getBic(), event.getOpenedDate(), event.getCurrency(), event.getBalance(), event.getAvailableBalance(), event.getCustomer(), event.getInstitution(), event.getTransactions(), event.getCards(), event.getStatements(), event.getMandates(), event.getAccountType(), event.getStatus()));
    }

    /*
     * @param	event UpdateAccountEvent
     */
    @EventHandler
    public Account handle( UpdateAccountEvent event) {
    	entityManager.merge(new Account(event.getAccountId(), event.getAccountNumber(), event.getIban(), event.getBic(), event.getOpenedDate(), event.getCurrency(), event.getBalance(), event.getAvailableBalance(), event.getCustomer(), event.getInstitution(), event.getTransactions(), event.getCards(), event.getStatements(), event.getMandates(), event.getAccountType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteAccountEvent
     */
    @EventHandler
    public void on( DeleteAccountEvent event) {
    	Account entity = new Account();
   
    	// ------------------------------------------
    	// apply the AccountId
    	// ------------------------------------------
    	entity.setAccountId( event.getAccountId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AccountRepository accountEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AccountEventHandler.class.getName());

}
